fast_pseudocode:
# Autotuned XBLOCK in {16,32,64}, 40 registers/thread selected
@triton.autotune(configs=[
    triton.Config({'XBLOCK': 16}, num_warps=2),
    triton.Config({'XBLOCK': 32}, num_warps=2),
    triton.Config({'XBLOCK': 32}, num_warps=4),
    triton.Config({'XBLOCK': 64}, num_warps=4),
], key=['xnumel', 'r0_numel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    ...

grid = (triton.cdiv(xnumel, 128),)  # grid unchanged; autotune picks best XBLOCK
kernel[grid](...)  # no explicit XBLOCK arg
